#!/usr/bin/env bash
# Run this from the ROOT of your React Native project (where package.json lives).
set -e
echo "Filling in stub screens: Sound/Vibration/Avatar settings + real biometric enrollment..."
mkdir -p components screens

echo "  components/OptionRow.js"
mkdir -p "$(dirname 'components/OptionRow.js')"
echo '' | base64 --decode > 'components/OptionRow.js'

echo "  screens/SoundSettingsScreen.js"
mkdir -p "$(dirname 'screens/SoundSettingsScreen.js')"
echo '' | base64 --decode > 'screens/SoundSettingsScreen.js'

echo "  screens/VibrationSettingsScreen.js"
mkdir -p "$(dirname 'screens/VibrationSettingsScreen.js')"
echo '' | base64 --decode > 'screens/VibrationSettingsScreen.js'

echo "  screens/AvatarPreferenceScreen.js"
mkdir -p "$(dirname 'screens/AvatarPreferenceScreen.js')"
echo '' | base64 --decode > 'screens/AvatarPreferenceScreen.js'

echo "  screens/NotificationSettingsScreen.js"
mkdir -p "$(dirname 'screens/NotificationSettingsScreen.js')"
echo '' | base64 --decode > 'screens/NotificationSettingsScreen.js'

echo "  screens/ProfileScreen.js"
mkdir -p "$(dirname 'screens/ProfileScreen.js')"
echo '' | base64 --decode > 'screens/ProfileScreen.js'

echo "  screens/EditDetailsScreen.js"
mkdir -p "$(dirname 'screens/EditDetailsScreen.js')"
echo '' | base64 --decode > 'screens/EditDetailsScreen.js'

echo "  App.js"
mkdir -p "$(dirname 'App.js')"
echo '' | base64 --decode > 'App.js'

echo "  package.json"
mkdir -p "$(dirname 'package.json')"
echo '' | base64 --decode > 'package.json'

echo "  app.json"
mkdir -p "$(dirname 'app.json')"
echo '' | base64 --decode > 'app.json'

echo "Installing expo-local-authentication..."
npx expo install expo-local-authentication

echo ""
echo "Done. Note: fingerprint/Touch ID works fine in Expo Go, but Face ID on iOS specifically needs a dev build (not supported in Expo Go)."
